CREATE TABLE public.personas (
    id integer NOT NULL,
    numero_documento character varying(10) NOT NULL,
    tipo_documento character varying(30) NOT NULL,
    primer_nombre character varying(30) NOT NULL,
    segundo_nombre character varying(30),
    apellidos character varying(60) NOT NULL,
    fecha_nacimiento date NOT NULL,
    genero character varying(20) NOT NULL,
    correo_electronico character varying(255) NOT NULL,
    celular character varying(10) NOT NULL,
    foto_url character varying(500),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    created_by integer,
    updated_by integer,
    CONSTRAINT personas_genero_check CHECK (((genero)::text = ANY ((ARRAY['Masculino'::character varying, 'Femenino'::character varying, 'No binario'::character varying, 'Prefiero no reportar'::character varying])::text[]))),
    CONSTRAINT personas_tipo_documento_check CHECK (((tipo_documento)::text = ANY ((ARRAY['Tarjeta de identidad'::character varying, 'Cédula'::character varying])::text[])))
);


--
-- Name: personas_con_edad; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.personas_con_edad AS
 SELECT p.id,
    p.numero_documento,
    p.tipo_documento,
    p.primer_nombre,
    p.segundo_nombre,
    p.apellidos,
    p.fecha_nacimiento,
    p.genero,
    p.correo_electronico,
    p.celular,
    p.foto_url,
    p.created_at,
    p.updated_at,
    p.created_by,
    p.updated_by,
    EXTRACT(year FROM age((p.fecha_nacimiento)::timestamp with time zone)) AS edad,
        CASE
            WHEN (EXTRACT(year FROM age((p.fecha_nacimiento)::timestamp with time zone)) < (18)::numeric) THEN 'Menor de edad'::text
            WHEN ((EXTRACT(year FROM age((p.fecha_nacimiento)::timestamp with time zone)) >= (18)::numeric) AND (EXTRACT(year FROM age((p.fecha_nacimiento)::timestamp with time zone)) <= (65)::numeric)) THEN 'Adulto'::text
            ELSE 'Adulto mayor'::text
        END AS grupo_edad
   FROM public.personas p;


